    if apiErr != nil { writeError(c, apiErr); return }

    // service_name is optional: omitted cleans every service; an explicit
    // value must be non-empty and scopes the cleanup to that one service.
    serviceName := ""
    scopeAll := true
    if value, ok := bag.get(serviceNameKeys); ok {
        serviceName = strings.TrimSpace(stringValue(value))
        if serviceName == "" {
            writeError(c, errInvalidParameter("service_name must not be empty"))
            return
        }
        scopeAll = false
    }

    evaluateValue, ok := bag.get(evaluateAtKeys)
    if !ok {
        writeError(c, errInvalidParameter("evaluate_at is required"))
        return
    }
    evaluateAt, ok := parseTimeValue(evaluateValue)
    if !ok {
        writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
        return
    }
    timeoutValue, ok := bag.get(timeoutKeys)
    if !ok {
        writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
        return
    }
    timeout, ok := parseTimeout(timeoutValue)
    if !ok || timeout <= 0 {
        writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
        return
    }

    var instances []store.Instance
    var err error
    if scopeAll {
        instances, err = s.store.ListAllInstances()
    } else {
        instances, err = s.store.ListInstances(serviceName)
    }
    if err != nil {
        writeError(c, errStorageUnavailable())
        return
    }
    for _, instance := range instances {
        if evaluateAt.Before(instance.HeartbeatAt) {
            writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
            return
        }
    }

    lost := make([]store.InstanceKey, 0)
    for _, instance := range instances {
        if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
            lost = append(lost, store.InstanceKey{ServiceName: instance.ServiceName, InstanceID: instance.InstanceID})
        }
    }

    removed := make([]store.Instance, 0)
    if len(lost) > 0 {
        removed, err = s.store.DeleteInstances(lost)
        if err != nil {
            writeError(c, errStorageUnavailable())
            return
        }
    }

    deleted := make([]gin.H, 0, len(removed))
    for _, instance := range removed {
        deleted = append(deleted, instanceJSON(instance))
    }
    // sort by service_name asc, instance_id asc
    sort.SliceStable(deleted, func(i, j int) bool {
        left, right := deleted[i], deleted[j]
        if left["service_name"] != right["service_name"] {
            return stringValue(left["service_name"]) < stringValue(right["service_name"])
        }
        return stringValue(left["instance_id"]) < stringValue(right["instance_id"])
    })

    c.JSON(200, gin.H{
        "evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
        "heartbeat_timeout": jsonWeight(timeout.Seconds()),
        "removed":           len(deleted),
        "instances":         deleted,
    })
}
```

Wait — one issue: `instances` should be an empty array `[]` in JSON, not `null`. `make([]gin.H, 0)` marshals to `[]`. Good.

Sorting: ListAllInstances already returns ordered by service_name, instance_id. ListInstances — no ORDER BY. To be safe, sort explicitly. Since the requirement says "按 service_name 升序、instance_id 升序排列", I'll sort explicitly.

Note about `removed`: should it count the records actually deleted (from DeleteInstances return) — yes, "removed 数量和 instances 列表；instances 是刚删除的完整实例记录". So removed == len(instances).

Now the store method. Let me write it:

```go
// InstanceKey identifies one instance record by its primary key.
type InstanceKey struct {
    ServiceName string
    InstanceID  string
}

// DeleteInstances removes the identified records in a single transaction and
// returns the records exactly as they were right before deletion. Records
// that no longer exist are skipped; any storage failure rolls the whole
// transaction back so no partial deletion is left behind.
func (s *Store) DeleteInstances(keys []InstanceKey) ([]Instance, error) {
    tx, err := s.db.Begin()
    if err != nil {
        return nil, err
    }
    defer tx.Rollback()

    removed := make([]Instance, 0, len(keys))
    for _, key := range keys {
        row := tx.QueryRow(`
SELECT service_name, instance_id, address, port, healthy, weight, heartbeat_at
FROM service_instances
WHERE service_name = ? AND instance_id = ?`, key.ServiceName, key.InstanceID)
        instance, err := scanInstance(row)
        if err == sql.ErrNoRows {
            continue
        }
        if err != nil {
            return nil, err
        }
        if _, err := tx.Exec(`
DELETE FROM service_instances WHERE service_name = ? AND instance_id = ?`, key.ServiceName, key.InstanceID); err != nil {
            return nil, err
        }
        removed = append(removed, instance)
    }

    if err := tx.Commit(); err != nil {
        return nil, err
    }
    return removed, nil
}
```

